INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132022, 'spa', 'Ser pequeño o disminuir', 'En Génesis 32:10 Jacob declara «soy indigno (קָטֹנְתִּי) de toda la bondad», expresando humildad ante las bendiciones de Dios. En 2 Samuel 7:19 y 1 Crónicas 17:17, David se asombra: «esto fue poca cosa a tus ojos» (וַתִּקְטַן זֹאת בְּעֵינֶיךָ). Amós 8:5 condena a quienes «achican la efa» (לְהַקְטִין הָאֵיפָה), usando medidas fraudulentas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132024, 'spa', 'El sentido adjetival básico', 'El sentido adjetival básico: pequeño en tamaño físico, cantidad o importancia. Abarca desde piedras pequeñas (Dt 25:13) hasta asuntos insignificantes (Nm 22:18). Cuando se aplica a personas, suele implicar insignificancia social más que estatura física, como en la juventud de David frente a Goliat (1 Sam 17:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132025, 'spa', 'Joven o menor en edad, especialmente dentro de relaciones entre hermanos', 'Joven o menor en edad, especialmente dentro de relaciones entre hermanos. Frecuentemente sustantivado con el artículo -- haqqatan, ''el menor'' -- como con Jacob (Gn 27:42) y Raquel (Gn 29:16). El patrón de Dios eligiendo al menor por encima del mayor (Gn 9:24; 1 Sam 16:11) hace de este sentido algo teológicamente cargado a lo largo de las narrativas patriarcales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132034, 'spa', 'Uso superlativo o elativo', 'Uso superlativo o elativo: el menor, el más pequeño, el miembro más insignificante de un grupo. A menudo construido con min (de) o un sufijo posesivo -- ''desde el menor de ellos'' (Jer 6:13; 42:1). Saúl protesta que es del clan más pequeño (1 Sam 9:21). Este sentido posee peso teológico: Dios obra repetidamente a través de lo que es qatan a los ojos del mundo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132047, 'spa', 'Pequeño, insignificante', 'Pequeño, insignificante: pequeño en tamaño, cantidad o importancia — el sentido adjetival básico. Moisés juzga los asuntos «pequeños» junto con los grandes (Éx 18:22, 26), Ana confecciona un «pequeño» manto para Samuel cada año (1 S 2:19) y Saúl protesta ''¿No soy yo insignificante?'' reclamando su poca importancia antes de su unción (1 S 15:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132048, 'spa', 'Menor, más joven', 'Menor, más joven: menor o más joven en edad, o el de menor rango — el sentido comparativo y superlativo usado especialmente en contextos familiares. Los hermanos de José identifican a Benjamín como «el menor» (Gn 42:13, 15, 20, 32), Jacob cruza las manos para bendecir al menor Efraín sobre Manasés (Gn 48:14, 17) y David es descrito como «el más joven» entre sus hermanos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132049, 'spa', 'Desde el menor (fórmula de rango)', 'Desde el menor (fórmula de rango): uso formulaico con la preposición מִן en la expresión «desde el menor hasta el mayor» (מִקָּטֹן וְעַד־גָּדוֹל), marcando el extremo inferior de un rango social o etario completo. En Sodoma, «desde el menor hasta el mayor» acosaban a Lot (Gn 19:11); en Asdod, la mano del SEÑOR hirió «desde el menor hasta el mayor» (1 S 5:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132063, 'spa', 'arrancar vegetacion', 'Arrancar o cortar vegetacion — ramas, espigas o plantas — con la mano. Las cinco ocurrencias implican material vegetal: el aguila que arranca renuevos de cedro (Ez 17:4, 22), el espigueo de grano (Dt 23:25), los indigentes que arrancan malvas (Job 30:4) y la forma pasiva nifal ''ser arrancado'' (Ez 17:9). El campo semantico converge en la remocion manual y enérgica de plantas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132064, 'spa', 'quemar sacrificio en el altar (Hifil)', 'El Hifil designa la acción de hacer subir en humo la grasa, las entrañas o los holocaustos sobre el altar — el acto sacrificial levítico por excelencia. Concentrado en Éxodo y Levítico (Éx 29:13, 18, 25; Lv 1-9), este sentido constituye el término técnico para la quema sacerdotal de las porciones sacrificiales, distinto de la mera incineración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132066, 'spa', 'quemar incienso (Piel)', 'El Piel designa el acto ritual de quemar incienso como adoración o, frecuentemente, como práctica idolátrica. Dominante en las condenas proféticas de Jeremías y Oseas (Jer 19:13; Os 11:2), donde Israel quema incienso a dioses ajenos. Las 50 ocurrencias abarcan tanto el servicio legítimo del templo como la fumigación cultual ilegítima, sin que la conjugación misma distinga entre ambos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132069, 'spa', 'quemar incienso (Hifil)', 'Un uso del Hifil semánticamente equivalente al Piel ''quemar incienso'', que aparece especialmente en Reyes y Crónicas para describir el culto en los lugares altos o ante el altar del incienso del templo (Éx 30:7-8; 1 R 11:8; 13:2). Las 18 ocurrencias sugieren que el Hifil podía asumir un significado de incienso junto al de ofrenda en el altar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132102, 'spa', 'ser quemado (pasivo)', 'Una única ocurrencia pasiva en Lv 6:15 (6:22 en el TM) donde la ofrenda vegetal del sacerdote ungido ''será quemada'' enteramente. Se trata probablemente de una forma Hofal o Pual que describe la consumición completa, distinta del humear estándar del Hifil sobre el altar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132108, 'spa', 'perfumada (uso poético)', 'Un uso participial único en Cantares 3:6 que describe la litera de Salomón como ''perfumada con'' mirra e incienso. Este empleo poético revela el significado subyacente de la raíz — producir humo fragante — antes de su especialización en vocabulario cultual. Es el sentido aromático, no sacrificial, de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132119, 'spa', 'Articulaciones/nudos', 'Dos usos en Daniel 5: anatómico (las articulaciones del rey aflojándose por miedo, v.6) e intelectual/mágico (resolver nudos/dificultades, vv.12, 16). La evidencia translingüística muestra esta tensión: algunas traducciones dan ''articulaciones'' (anatómico), otras ''nudos'' (problemas), algunas ponen entre paréntesis las formas (alemán/francés) notando incertidumbre. El sentido literal implica cosas atadas juntas (articulaciones, nudos), mientras que el figurativo extiende esto a problemas complejos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132122, 'spa', 'Incienso, ofrenda aromática', 'Incienso, ofrenda aromática: el compuesto aromático de especias quemado ritualmente ante YHWH, tanto la sustancia en sí como el humo fragante que produce (Éx 25:6; 30:1, 7-8, 34-38). Se empleaba a diario sobre el altar del incienso en el tabernáculo y el templo (Lv 16:13; Nm 16:7, 17-18; 2 Cr 29:7), y fue ofrecido por los príncipes tribales en la dedicación (Nm 7:14, 86). El Salmo 141:2 equipara metafóricamente la oración con el incienso que asciende.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132138, 'spa', 'Humo espeso', 'Génesis 19:28 menciona dos veces «el humo de la tierra subió como el humo de un horno» (כְּקִיטֹר הַכִּבְשָׁן) tras la destrucción de Sodoma. El Salmo 119:83 usa una imagen vívida: «soy como un odre en el humo» (כְּנֹאד בְּקִיטוֹר), marchito y ennegrecido. El Salmo 148:8 presenta incertidumbre textual: el hebreo dice «humo» pero versiones antiguas sugieren «escarcha».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132145, 'spa', 'Caín (nombre propio)', 'Caín (nombre propio): Caín (קַיִן), el nombre personal del hijo primogénito de Adán y Eva, cuya historia en Génesis 4 abarca la primera adoración, el primer fratricidio y el primer exilio. El nombre está etimológicamente vinculado a קָנָה (''adquirir/crear'') mediante la declaración de Eva al nacer (Gn 4:1). Todas las ocurrencias pertenecen a la narrativa de Génesis 4:1-25, trazando su ofrenda, su asesinato de Abel, su diálogo con Dios y su marca protectora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132148, 'spa', 'Lamentación, endecha, canto fúnebre', 'Lamentación, endecha, canto fúnebre: una endecha o canto fúnebre formal, caracterizado por el ritmo de la קִינָה con hemistiquios desiguales (acentos 3+2). Usado para lamentos sobre los muertos (2 S 1:17, David sobre Saúl) y cantos fúnebres proféticos sobre naciones y ciudades. A Ezequiel se le ordena repetidamente ''elevar una קִינָה'' (Ez 19:1; 26:17; 27:2; 28:12; 32:2). Jeremías lo empareja con el llanto (Jer 9:10) y llama a las plañideras a enseñarlo (9:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132156, 'spa', 'Cenita (gentilicio) — Miembro del pueblo cenita, un clan vinculado a Caín/קַיִן ', 'Cenita (gentilicio) — Miembro del pueblo cenita, un clan vinculado a Caín/קַיִן y conocido por su vida seminómada y la metalurgia. Mantuvieron una alianza persistente con Israel desde el período del desierto en adelante. Figuras clave incluyen a Jael, esposa de Heber el cenita (Jue 4:11, 17; 5:24), el suegro cenita de Moisés (Jue 1:16) y los descendientes recabitas trazados hasta orígenes cenitas (1 Cr 2:55). El oráculo de Balaam (Nm 24:21–22) hace un juego de palabras entre קֵן (''nido'') y el nombre del clan, describiendo su asentamiento como un nido puesto en la roca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132163, 'spa', 'Quenán (nombre propio)', 'El nombre propio masculino Quenán (Cainán), patriarca antediluviano en el linaje de Set. Las seis ocurrencias aparecen en listas genealógicas: Génesis 5:9 registra su nacimiento de Enós a los 90 años, Génesis 5:10-13 traza sus 840 años restantes y descendencia, Génesis 5:14 consigna su muerte a los 910 años, y 1 Crónicas 1:2 repite su lugar en el linaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132165, 'spa', 'Verano (estación)', 'Verano (estación): la estación cálida y seca del año, emparejada con ''invierno'' en merismos que abarcan todo el año (Gn 8:22; Sal 74:17; Zac 14:8). Proverbios presenta a la hormiga como sabia por preparar alimento ''en el verano'' (Pr 6:8; 10:5), y el Salmo 32:4 describe la humedad secándose ''como en el calor del verano''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132167, 'spa', 'Fruta de verano', 'Fruta de verano: fruta madura recogida durante la estación de verano, especialmente higos y productos similares de cosecha tardía. Aparece en relatos de aprovisionamiento (2 S 16:1-2), juicio profético mediante el juego de palabras קַיִץ/קֵץ (Am 8:1-2), e instrucciones sobre la recolección de la cosecha (Jer 40:10, 12). Miqueas 7:1 lamenta no encontrar fruta de verano como metáfora de decadencia moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132175, 'spa', 'Extremo o exterior', 'Éxodo 26:4 y 26:10 (con paralelos en 36:11 y 36:17) describen la confección de lazadas en el borde de «la cortina extrema» (הַיְרִיעָה הַקִּיצֹנָה) de cada juego. Esto indica cuál cortina de la serie recibe las lazadas de unión para conectar los juegos entre sí, siendo un término técnico clave para el ensamblaje correcto del tabernáculo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132176, 'spa', 'planta de ricino', 'Planta especifica — muy probablemente el ricino (Ricinus communis) — dispuesta por Dios para dar sombra a Jonas. La identificacion se remonta a Jeronimo y la Septuaginta (κολοκύνθη en algunos manuscritos). Las cinco ocurrencias se concentran en Jonas 4:6-10, trazando el crecimiento milagroso de la planta, el deleite de Jonas en ella y su destruccion por un gusano al amanecer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132178, 'spa', 'Pared (edificio/interior)', 'Pared (edificio/interior): pared estructural perteneciente a un edificio, casa o templo — el sentido dominante que abarca casi todas las apariciones. Ya sea salpicada con sangre sacrificial (Lv 1:15; 5:9), inspeccionada en busca de moho (Lv 14:37, 39) o formando las divisiones interiores del templo de Salomón, קִיר es la palabra cotidiana para una pared construida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132188, 'spa', 'Muro (ciudad/fortificación)', 'Muro (ciudad/fortificación): muro urbano o barrera de fortificación, donde קִיר se solapa con el más frecuente חוֹמָה. Atestiguado en solo cuatro pasajes (Nm 35:4; Is 22:5; 25:4; 59:10), estos contextos involucran estructuras defensivas e imágenes de asedio. El español distingue naturalmente entre «pared» (pared de habitación) y «muro» (estructura de mampostería), reflejando el cambio semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132205, 'spa', 'Topónimo: Kir', 'En 2 Reyes 16:9 Asiria deporta a Damasco «a Kir» (קִירָה). Isaías 22:6 menciona a Kir en coalición militar con Elam. Amós 1:5 profetiza el exilio de Aram «a Kir», y Amós 9:7 recuerda que Dios trajo «a los arameos desde Kir». Los contextos sugieren una región en Mesopotamia o Siria, posiblemente en el alto Éufrates, aunque la identificación definitiva permanece incierta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132206, 'spa', 'Kir-Hareset (topónimo)', 'El nombre propio Kir-Hareset (también Kir-Heres), que designa una importante ciudad fortificada moabita, probablemente la moderna al-Karak en Jordania. El nombre combina qir (''muro'') con chareseth (''alfarería/tiesto''). Aparece en la campaña contra Moab (2 R 3:25) y en oráculos proféticos de juicio sobre Moab (Is 16:7, 11; Jer 48:31, 36), donde su destrucción suscita lamentación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132212, 'spa', 'Quis (nombre propio) — Nombre propio (קִישׁ) que designa a varios individuos en ', 'Quis (nombre propio) — Nombre propio (קִישׁ) que designa a varios individuos en la Biblia hebrea. El más famoso es Quis el benjamita, padre de Saúl, primer rey de Israel (1 Sam 9:1; 10:21; 1 Cr 8:33). Un levita llamado Quis aparece en la administración davídica (1 Cr 23:21; 24:29), y Ester 2:5 nombra a Quis en el linaje de Mardoqueo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132216, 'spa', 'Qishón', 'El Qishón (Cisón), río o wadi estacional en el valle de Jezreel, al norte de Israel, asociado con dos intervenciones divinas extraordinarias. En el relato de Débora y Barac, Dios usa el Cisón crecido para arrastrar los carros de Sísara (Jue 4:7, 13), y el cántico de Débora celebra cómo «el torrente Cisón los arrastró, aquel antiguo torrente» (Jue 5:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132219, 'spa', 'Lira o cítara', 'Una lira o cítara, préstamo arameo del griego kitharis (κίθαρις), que aparece solo en Daniel 3:5, 7, 10, 15 entre los instrumentos tocados en la dedicación de la imagen de oro de Nabucodonosor. Las formas ketiv y qere (qithros/qathros) reflejan variantes ortográficas de este helenismo en el arameo imperial. La evidencia interlingüística lo identifica uniformemente como un instrumento de cuerdas pulsadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132221, 'spa', 'Veloz, rápido, ligero — Rápido, ágil, ligero en movimiento; se aplica a personas', 'Veloz, rápido, ligero — Rápido, ágil, ligero en movimiento; se aplica a personas (Asael, 2 S 2:18; guerreros, Am 2:14–15), animales (una camella ligera, Jer 2:23), fenómenos naturales (una nube ligera, Is 19:1) y agentes abstractos (la veloz desaparición de los malvados, Job 24:18). La palabra puede funcionar como sustantivo (''el veloz'', Is 30:16; Ec 9:11) o adverbialmente (''velozmente'', Is 5:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132230, 'spa', 'Sonido o voz', 'Sonido o voz — equivalente arameo del hebreo qol, que abarca tanto el sonido instrumental como la voz hablada. En Daniel 3:5, 7, 10 y 15, aparece en estado constructo (''sonido del cuerno, la flauta, la cítara...'') para la señal musical que ordena la adoración de la imagen de oro. En Daniel 4:31 es la voz celestial que cae sobre Nabucodonosor anunciando la pérdida de su reino, y en 6:20 es la voz angustiada del rey.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132233, 'spa', 'Tostar o quemar', 'Levítico 2:14 prescribe una ofrenda de «grano tostado al fuego» (אָבִיב קָלוּי בָּאֵשׁ). Josué 5:11 menciona «grano tostado» (קָלוּי) consumido el día después de la Pascua. El Salmo 38:7 dice «mis lomos están llenos de ardor» (נִקְלֶה; algunas versiones leen «desprecio»). Jeremías 29:22 advierte que Nabucodonosor «los quemó en el fuego» (קָלָם בָּאֵשׁ).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132234, 'spa', 'Ser menospreciado (Nifal)', 'Ser menospreciado, tenido en poco o deshonrado (Nifal pasivo/estativo). Describe la disminución social: Isaías 3:5 contrasta al «vil» (niqle) con el «honorable» (nikhbad). En 1 Samuel 18:23, David se califica a sí mismo como pobre y niqle. El término español «despreciado» capta con precisión el sentido pasivo de pérdida de posición social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132237, 'spa', 'Deshonrar (Hifil)', 'Deshonrar o tratar con desprecio (Hifil causativo). Aparece únicamente en la fórmula de maldición del pacto en Deuteronomio 27:16, donde quien «deshonra» (maqleh) a su padre o madre queda maldito. La expresión «el que deshonrare» capta el acto deliberado y causativo que se opone directamente al mandamiento de «honrar» (kabbed) a los padres.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132240, 'spa', 'Vergüenza, deshonra, ignominia — Vergüenza o deshonra como condición públicament', 'Vergüenza, deshonra, ignominia — Vergüenza o deshonra como condición públicamente visible, ya sea personal o nacional. En la literatura sapiencial se opone a כָּבוֹד (''gloria, honor'') como consecuencia de la necedad y la maldad (Prov 3:35; 6:33; 11:2). En el uso profético designa la humillación de naciones bajo juicio divino, a veces con la imagen gráfica de desnudez expuesta (Jer 13:26; Nah 3:5). Job 10:15 lo aplica al sufrimiento individual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132249, 'spa', 'Grano tostado', 'Grano tostado o cereal tostado: espigas frescas de trigo o cebada secadas y tostadas al fuego como alimento listo para consumir. Se emplea en comidas cotidianas (Rut 2:14), provisiones militares (1 Sam 17:17, 25:18; 2 Sam 17:28) y está regulado en la legislación sacerdotal (Lev 23:14). La palabra deriva de la raíz qalah, «tostar».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132256, 'spa', 'Levita en reformas post-exílicas', 'Tres contextos post-exílicos definen a Quelita: la controversia de esposas extranjeras (Esdras 10:23, donde también se le llama Quelaías), enseñanza pública de la Torá (Nehemías 8:7) y sellamiento del pacto (10:10). Las formas entre paréntesis en alemán y francés simplemente marcan el nombre hebreo. Este levita participó en momentos clave de reforma—separación de influencia extranjera, instrucción bíblica y rededicación comunitaria. Su nombre dual sugiere identidad compleja o cambio de nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132257, 'spa', 'Hifil', 'Hifil: aligerar una carga: en el Hifil causativo, significa hacer una carga físicamente más ligera — reducir el peso de un yugo o una carga. Jetro aconseja a Moisés aligerar su carga judicial (Éx 18:22), e Israel suplica a Roboam que aligere el duro yugo de Salomón (1 R 12:4-10). Las nueve apariciones se agrupan en torno a contextos administrativos y políticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132258, 'spa', 'Qal', 'Qal: ser veloz: en Qal describe movimiento rápido — ser veloz o más rápido de lo normal. Job lamenta que sus días «son más veloces que la lanzadera del tejedor» (Job 7:6), y Jeremías advierte que los carros enemigos se acercan «más veloces que águilas» (Jer 4:13). Cinco pasajes emplean este sentido, frecuentemente en lamentos poéticos sobre la fugacidad de la vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132259, 'spa', 'Piel', 'Piel: maldecir: la forma intensiva Piel expresa el acto solemne de pronunciar una maldición — declarar a alguien maldito ante Dios y la comunidad. Aparece 41 veces, siendo el sentido más frecuente, especialmente en contextos de alianza (Gn 12:3; Éx 21:17). La evidencia multilingüe converge uniformemente en el acto ritual de invocar juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132262, 'spa', 'Nifal', 'Nifal: ser cosa ligera, trivial: la forma Nifal expresa que algo es un asunto leve o fácil — algo trivial o que requiere poco esfuerzo. Cuando David considera casarse con la hija de Saúl, protesta: «¿Es cosa ligera ser yerno del rey?» (1 S 18:23). El doble milagro de Eliseo es «poca cosa» a los ojos de Dios (2 R 3:18). Siete atestiguaciones muestran este sentido de facilidad o insignificancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132267, 'spa', 'Nifal', 'Nifal: ser veloz, ligero (en movimiento): un sentido especializado del Nifal que describe rapidez o ligereza de movimiento — moverse ágilmente. Isaías advierte contra los falsos profetas que «curaron la herida de mi pueblo a la ligera» (Jer 6:14; 8:11) — tratando asuntos graves con prisa superficial. Tres atestiguaciones muestran acción realizada sin la gravedad debida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132269, 'spa', 'Pual', 'Pual: ser maldecido: la forma pasiva Pual indica ser objeto de una maldición — recibir una maldición como receptor pasivo. Job describe al impío cuya porción «es maldita en la tierra» (Job 24:18), e Isaías profetiza que quien muera a los cien años será considerado «maldito» (Is 65:20). Dos pasajes emplean esta construcción pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132274, 'spa', 'Sentido incierto con una sola atestiguación que describe montañas que «se estrem', 'Sentido incierto con una sola atestiguación que describe montañas que «se estremecían» o temblaban (Jer 4:24) en una visión apocalíptica. La naturaleza de hapax dificulta una definición precisa, aunque el contexto sugiere sacudida violenta o temblor de la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132275, 'spa', 'Qal', 'Qal: ser insignificante, despreciado: el Qal puede denotar ser tratado como insignificante o despreciado — de poca importancia a los ojos de alguien. Cuando Agar concibe, Sara es «despreciada a sus ojos» (Gn 16:4-5), y Dios advierte que quienes lo desprecien «serán tenidos en poco» (1 S 2:30). Job confiesa «soy insignificante» ante la majestad de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132278, 'spa', 'Qal', 'Qal: menguar, disminuir: en Qal describe aguas que menguan o disminuyen — volverse más ligeras o bajar de nivel. Después del diluvio, Noé envía una paloma para ver «si las aguas habían disminuido sobre la faz de la tierra» (Gn 8:8, 11). Dos apariciones en el relato del diluvio preservan este sentido concreto de aguas que retroceden.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132279, 'spa', 'Piel', 'Piel: sacudir, agitar: un sentido Piel distinto que significa sacudir, blandir o afilar — agitar algo físicamente. El Predicador advierte: «si el hierro está embotado y no se afila el filo» (Ec 10:10), y Ezequiel ve al rey de Babilonia «sacudiendo las flechas» para la adivinación (Ez 21:21). Semánticamente distante del sentido de maldecir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132282, 'spa', 'Hifil', 'Hifil: tratar con ligereza, deshonrar: el Hifil causativo aquí significa tratar a alguien con ligereza — deshonrar, despreciar o mostrar menosprecio por su dignidad. Dios pregunta a Acaz: «¿Es poca cosa para vosotros fatigar a los hombres, que también fatigaréis a mi Dios?» (Is 7:13). Cuatro pasajes muestran este sentido de deshonra deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132307, 'spa', 'Otra atestiguación única e incierta donde David dice «me humillaré aún más» (2 S', 'Otra atestiguación única e incierta donde David dice «me humillaré aún más» (2 S 6:22) al adorar delante del arca. El matiz reflexivo del Hitpael o Nifal aquí no es claro — si David quiere decir que aceptará ser despreciado o que activamente se rebajará. La forma gramatical única y el contexto dificultan la clasificación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132322, 'spa', 'Pronunciamiento solemne que invoca daño divino o el estado resultante de estar m', 'Pronunciamiento solemne que invoca daño divino o el estado resultante de estar maldito. Aparece con mayor frecuencia en antítesis con berakhah (''bendición'') en fórmulas de pacto (Dt 11:26-28; Jos 8:34). Abarca la disposición de Rebeca a cargar con la maldición de Jacob (Gn 27:12-13), la maldición infundada de Pr 26:2, la grave maldición de Simí contra David (1 R 2:8) y el uso reiterado de Jeremías para describir la suerte de naciones convertidas en objeto de horror y maldición (Jer 24:9; 25:18; 29:22; 44:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132332, 'spa', 'Burlarse con desprecio', 'La conjugacion Hitpael intensifica el acto de mofarse o escarnecer a alguien, tipicamente con una preposicion que marca el objeto del desprecio. En 2 Reyes 2:23, unos jovenes se burlan de Eliseo; en Habacuc 1:10, los caldeos se mofan de las fortalezas; Ezequiel lo emplea dos veces (16:31; 22:5) en contextos de juicio profetico. Las traducciones al español ''se-burla/se-burlarán'' reflejan la fuerza reflexiva de la raiz hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132333, 'spa', 'Escarnio público', 'Los tres usos expresan ser objeto de burla: Israel como nación fracasada (Salmos 44, 79) y Jeremías como profeta despreciado. El emparejamiento con ''oprobio'' y ''burla'' es consistente, sugiriendo una expresión fija para humillación comunal o personal. La evidencia translingüística (español ''burla/escarnio'', francés ''dérision'', alemán ''derision'') confirma el significado: ser tratado como objeto de burla o desprecio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132335, 'spa', 'Lanzar con honda', 'El verbo abarca tanto el lanzamiento literal de piedras con honda (los honderos zurdos de Benjamin en Jueces 20:16 que acertaban ''a un cabello''; 1 Samuel 17:49 donde David lanza contra Goliat) como el arrojamiento metaforico (Jeremias 10:18, Dios arrojando a los habitantes de Juda; 1 Samuel 25:29, vidas lanzadas lejos). Las glosas multilingues confirman esta coherencia semantica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132336, 'spa', 'Tallar diseños sagrados', 'El término se refiere consistentemente al proceso técnico de grabar o esculpir imágenes religiosas decorativas en superficies del templo. Las glosas multilingües enfatizan la precisión artística involucrada—ya sea tallando querubines, palmeras o flores abiertas en las paredes y puertas del Lugar Santísimo. Esta era una artesanía especializada reservada para arquitectura sagrada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132337, 'spa', 'Honda (arma)', 'Honda: arma compuesta por una bolsa de cuero o tela con cuerdas, usada para lanzar piedras a gran velocidad. Atestiguada en el relato de David y Goliat (1 Sam 17:40, 50), en la vívida metáfora de Abigail sobre la protección divina frente al juicio divino (1 Sam 25:29), y en inventarios militares (2 Cr 26:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132342, 'spa', 'Cortinas del Tabernáculo — Las cortinas tejidas o colgaduras que formaban los mu', 'Cortinas del Tabernáculo — Las cortinas tejidas o colgaduras que formaban los muros del cercado del atrio del Tabernáculo, suspendidas de columnas a lo largo de los lados sur, norte, este y oeste. Se detallan en las narrativas de construcción de Éxodo (Éx 27:9-18; 35:17; 38:9-18) y en las asignaciones levíticas (Nm 3:26; 4:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132344, 'spa', 'Hojas de puerta — Variante textual probable en 1 Reyes 6', 'Hojas de puerta — Variante textual probable en 1 Reyes 6:34, donde el masorético קְלָעִים se enmienda ampliamente a צְלָעִים, referido a las hojas plegables o paneles de una puerta en el Templo de Salomón. BDB señala esto como una confusión de copista, indicando un sentido arquitectónico de paneles de puerta con bisagras, distinto de las colgaduras de tela.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132349, 'spa', 'Mies en pie', 'Cereal o cultivos que crecen erguidos en el campo, el sentido agrícola principal. Es el uso dominante, abarcando contextos legales (Éx 22:6; Dt 16:9; 23:25) y narrativos (Jue 15:5). El español «mies» y el francés «grain debout» reflejan la imagen de plantas de cereal altas y sin cosechar ondeando en campos abiertos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132353, 'spa', 'Crecimiento de cultivos', 'El crecimiento o maduración de los cultivos conforme se acercan a la sazón. Isaías 37:27 usa la palabra en un contexto donde la vegetación es arrasada «antes de ser mies en pie», señalando la etapa de desarrollo más que los tallos físicos. Esta extensión abstracta capta el proceso de llegar a plena madurez, no solo el producto terminado en el campo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132354, 'spa', 'Alzarse, ponerse erguido', 'Alzarse o estar erguido en un sentido abstracto y no agrícola. En 2 Reyes 19:26, el paralelismo con «sentarse» sugiere postura corporal —ponerse de pie frente a sentarse— en lugar de grano literal. El alemán «stehend» y el francés «debout» tienden un puente natural entre los significados agrícola y postural de esta raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132355, 'spa', 'Tallo, caña del grano', 'El tallo o caña de la planta de cereal, una restricción metonímica del cultivo entero al tallo individual erguido. Oseas 8:7 advierte que la siembra de Israel no producirá «mies en pie» —más precisamente, tallos sin espigas—. El español «tallo» capta este enfoque en la estructura de la planta, no en el campo como totalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132359, 'spa', 'Nombre propio masculino', 'Este nombre propio designa tres figuras bíblicas separadas: primero, uno de los hijos de Nacor en las genealogías de Génesis 22; segundo, un representante de la tribu de Efraín elegido para ayudar a dividir la Tierra Prometida; y tercero, un oficial levítico durante la administración de David. La transliteración consistente entre idiomas (Kemuel, Qemuel) preserva la forma fonética hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132362, 'spa', 'Harina, harina gruesa — Harina o harina gruesa (קֶמַח), el producto ordinario de', 'Harina, harina gruesa — Harina o harina gruesa (קֶמַח), el producto ordinario de grano molido usado en la elaboración diaria de pan y en ciertas ofrendas rituales. Es más gruesa que סֹלֶת (harina fina), como lo muestra su emparejamiento en 1 R 4:22. Aparece de manera destacada en relatos narrativos como la provisión milagrosa de la viuda de Sarepta (1 R 17:12–16), la ofrenda de Gedeón (Jue 6:19), y el banquete preparado por la médium de Endor para Saúl (1 S 28:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132368, 'spa', 'Puñado ritual sacerdotal', 'El término especifica la acción sacerdotal de agarrar un puñado ritual de ofrendas de grano e incienso. En Levítico 2:2 y 5:12, el sacerdote toma su puñado completo de flor de harina mezclada con aceite e incienso como porción memorial para quemar en el altar. Números 5:26 aplica este mismo gesto técnico a la ofrenda de grano en la prueba de celos. El contexto ritual consistente muestra que es terminología cultual especializada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132369, 'spa', 'Punado o puno', 'Designa un punado como parte del cuerpo (mano cerrada) y como medida. En Levitico 2:2, 5:12 y 6:15 (todos de fuente sacerdotal), el sacerdote toma ''un punado'' (מְלֹא קֻמְצוֹ, ''lo que llena su puno'') de la ofrenda de cereal como porcion conmemorativa. Genesis 41:47 usa el plural ''a punados'' para describir la abundante cosecha durante los siete anos de abundancia en Egipto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132371, 'spa', 'Nido de ave — Nido de un ave, usado tanto literalmente de la estructura construi', 'Nido de ave — Nido de un ave, usado tanto literalmente de la estructura construida por pájaros como metafóricamente de moradas humanas situadas en lugares altos, seguros o aparentemente inexpugnables. El uso literal aparece en la ley del nido de aves de Deuteronomio (Dt 22:6), el águila que agita su nido (Dt 32:11) y el águila de Job anidando en el peñasco (Job 39:27). La extensión metafórica es rica: Balaam juega con el nombre de los cenitas, Abdías y Jeremías se mofan de Edom por poner su nido en las alturas (Abd 4; Jer 49:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132376, 'spa', 'Compartimento o habitación — Habitación, celda o compartimento dentro de una est', 'Compartimento o habitación — Habitación, celda o compartimento dentro de una estructura mayor, específicamente los espacios divididos dentro del arca de Noé (Gn 6:14). Dios instruye a Noé hacer קִנִּים (''nidos/habitaciones'') en el arca, una vívida metáfora arquitectónica: cada compartimento es un nido que cobija a sus ocupantes durante el diluvio. Las traducciones abandonan el vocabulario aviar en favor de términos arquitectónicos como ''compartimentos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132381, 'spa', 'Envidiar a otra persona por sus ventajas, posición o bendiciones — la contrapart', 'Envidiar a otra persona por sus ventajas, posición o bendiciones — la contraparte corrosiva de los celos protectores del sentido 1. Con 11 apariciones en Piel, este sentido emerge cuando Raquel envidia la fertilidad de Lea (Gn 30:1), los filisteos envidian la riqueza de Isaac (Gn 26:14), los hermanos de José lo envidian (Gn 37:11), y el salmista advierte contra envidiar a los malvados (Sal 37:1; 73:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132382, 'spa', 'Estar celoso o ser celoso por alguien o algo que se posee o sobre lo cual se tie', 'Estar celoso o ser celoso por alguien o algo que se posee o sobre lo cual se tiene un derecho legítimo, ardiendo con pasión posesiva y devoción exclusiva. Con 17 apariciones, este sentido dominante en Piel abarca los celos del esposo en el ritual de la sotá (Nm 5:14, 30), el celo de Fineas que ''fue celoso por su Dios'' y detuvo la plaga (Nm 25:11, 13), la apasionada declaración de Elías y el celo divino por Jerusalén (Zac 1:14; 8:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132386, 'spa', 'Provocar a celos — la raíz causativa Hifil, que significa hacer que otro arda de', 'Provocar a celos — la raíz causativa Hifil, que significa hacer que otro arda de furia celosa mediante las propias acciones, especialmente por idolatría. Con 5 apariciones concentradas en Deuteronomio 32, el Cántico de Moisés, donde la adoración de Israel a ''no-dioses'' provocó los celos del SEÑOR (Dt 32:16, 21), y Dios responde simétricamente: ''Yo los provocaré a celos con un no-pueblo'' (Dt 32:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132406, 'spa', 'Celoso', 'Celoso — describe la insistencia de Dios en la lealtad exclusiva del pacto, sin tolerar rival en la adoración. Aparece solo como atributo divino: en la prohibición de idolatría del Decálogo (Éx 20:5; Deut 5:9), en la renovación del pacto donde el nombre mismo de Dios es «Celoso» (Éx 34:14), y en las advertencias mosaicas contra la apostasía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132408, 'spa', 'Celos como posesividad apasionada, ya sea la celotipia divina sobre Israel (Nm 2', 'Celos como posesividad apasionada, ya sea la celotipia divina sobre Israel (Nm 25:11; Ez 5:13) o la sospecha conyugal humana (Nm 5:14; Pr 6:34; 27:4). Cantares 8:6 lo empareja con el amor: ''los celos son crueles como el sepulcro.'' Este sentido abarca la emoción posesiva —no envidiosa— presente en las 33 apariciones del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132412, 'spa', 'Celo o devoción ardiente por Dios o su causa', 'Celo o devoción ardiente por Dios o su causa. Elías y Jehú arden de ''celo por el SEÑOR'' (2 R 10:16), el salmista es consumido por ''el celo de tu casa'' (Sal 69:9), e Isaías declara que ''el celo del SEÑOR de los ejércitos cumplirá esto'' (Is 9:7). Este sentido se distingue de los celos posesivos por su orientación positiva hacia la fidelidad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132418, 'spa', 'Envidia o rivalidad resentida hacia la prosperidad o el estatus de otro', 'Envidia o rivalidad resentida hacia la prosperidad o el estatus de otro. Eclesiastés observa que ''todo trabajo y toda excelencia de obra provoca la envidia del prójimo'' (4:4), y que en la muerte ''su envidia ya pereció'' (9:6). Este sentido marca una emoción negativa dirigida hacia la buena fortuna ajena, distinta de los celos protectores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132431, 'spa', 'Comprar, adquirir', 'Comprar, adquirir: el sentido comercial dominante — comprar o adquirir mediante transacción monetaria — que abarca 59 de las 86 apariciones. Incluye la compra de campos (Gn 25:10; 33:19; Jer 32:7-15), esclavos (Gn 47:19; Lv 22:11; 25:44-45), bienes y ganado. La forma participial קֹנֶה funciona como «comprador» en contextos de mercado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132433, 'spa', 'Adquirir, obtener', 'Adquirir, obtener: un sentido más amplio de adquirir u obtener bienes no comerciales — particularmente sabiduría, entendimiento, conocimiento y verdad en Proverbios (1:5; 4:5, 7; 16:16; 23:23). También se usa para Dios «adquiriendo» un pueblo (Éx 15:16; Sal 74:2; 78:54), donde la metáfora de compra se vuelve teológica — Israel como posesión atesorada de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132439, 'spa', 'Ser comprado (Nifal pasivo)', 'Ser comprado (Nifal pasivo): el Nifal pasivo — «ser comprado» — con tres apariciones, todas en la profecía de restauración de Jeremías: «se comprarán campos en esta tierra» (Jer 32:15, 43, 44). La voz pasiva desplaza el foco del comprador a la transacción misma como señal de esperanza — la tierra volverá a cambiar de manos en una Judá restaurada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132445, 'spa', 'Crear, poseer', 'Crear, poseer: un sentido teológico-cosmológico donde Dios es el originador o poseedor soberano — «Creador/Poseedor del cielo y de la tierra» (Gn 14:19, 22), «el que te hizo y te formó» (Dt 32:6), «tú me tejiste en el vientre de mi madre» (Sal 139:13), y la declaración de la Sabiduría: «el SEÑOR me poseía al principio de su obra» (Pr 8:22). Seis apariciones portan este sentido donde la adquisición se funde con la creación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132458, 'spa', 'Una aparición singular y enigmática en Ezequiel 8', 'Una aparición singular y enigmática en Ezequiel 8:3, donde el sustantivo סֵמֶל הַקִּנְאָה (''la imagen de los celos / la imagen provocadora'') aparece relacionado con קָנָה a través de la forma nominal קִנְאָה. El español «la que provoca celos» apunta a la derivación de קִנְאָה más que a un uso verbal directo de קָנָה, sugiriendo una conexión denominativa o etimológica con la provocación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132463, 'spa', 'Una aparición aislada en Zacarías 13', 'Una aparición aislada en Zacarías 13:5 — «un hombre me adquirió» o «un hombre me compró» — en el contexto de un falso profeta que niega su vocación, alegando haber sido labrador desde su juventud. Apunta a un significado comercial-servil, posiblemente «alguien me adquirió como siervo», vinculándose al sentido central de compra en un contexto biográfico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132487, 'spa', 'Caña, junco (planta)', 'Caña, junco (planta): el sentido primario designa la caña o junco que crece en pantanos y riberas, usada literalmente para la vegetación acuática (1 R 14:15; Is 19:6) y figuradamente como apoyo frágil (2 R 18:21, la «caña cascada»). La caña de medir de Ezequiel (40:3-5) deriva de la forma recta y rígida del tallo natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132488, 'spa', 'Brazo del candelabro', 'Brazo del candelabro: los seis brazos laterales que se extienden desde el fuste central de la menorá en las especificaciones del tabernáculo (Éx 25:32-36; 37:18-22). Cada קָנֶה es una extensión tubular y hueca que refleja la forma de una caña natural, una metáfora arquitectónica aplicada a la estructura sagrada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132493, 'spa', 'Fuste del candelabro', 'Fuste del candelabro: el eje vertical central del candelabro, del cual parten los seis brazos (Éx 25:31; 37:17). Solo dos apariciones distinguen esta pieza estructural del núcleo frente a los brazos laterales que se ramifican desde él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132495, 'spa', 'Tallo de grano', 'Tallo de grano: el tallo sobre el que crecen las espigas de grano, presente exclusivamente en los sueños del faraón (Gn 41:5, 22). Este sentido agrícola se distingue del junco de los humedales y destaca el tallo delgado y erguido que sostiene las espigas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132500, 'spa', 'Caña aromática, cálamo', 'Caña aromática, cálamo: cálamo fragante, una de las cuatro especias del aceite santo de la unción (Éx 30:23). Se distingue por el calificativo הַטּוֹב («el bueno») en Jer 6:20 y aparece junto a la canela y la alheña en Cnt 4:14. El contexto aromático separa este sentido de la caña común de los pantanos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132501, 'spa', 'Barra de balanza', 'Barra de balanza: la barra horizontal o travesaño de una balanza (Is 46:6), de la cual cuelgan los platillos para pesar. La forma rígida y alargada de una caña se transfiere al instrumento mecánico de pesaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132508, 'spa', 'Hueso del brazo', 'Hueso del brazo: el hueso del brazo superior en la articulación del hombro (Job 31:22), donde Job jura que su brazo debería caer de su קָנֶה si ha pecado. Esta extensión anatómica se basa en la forma tubular y alargada, un sentido corporal poco común.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132511, 'spa', 'Topónimo de Canaán', 'Este nombre de lugar se refiere a dos características geográficas distintas: el arroyo de Caná (naḥal Kanah) que servía como límite tribal entre Efraín y Manasés en Canaán central, y una ciudad asignada a Aser en el norte cerca de Tiro. Ambas ubicaciones probablemente derivaron sus nombres de cañas o juncos que crecían en el área, una base común para topónimos antiguos en regiones ricas en agua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132513, 'spa', 'Kenaz', 'Nombre propio llevado por al menos dos figuras: un descendiente edomita de Esaú enumerado entre los jefes de Edom (Gn 36:11, 15, 42) y el padre del juez Otoniel de la tribu de Judá (Jos 15:17; Jue 1:13; 3:9, 11). La coincidencia entre genealogías edomitas y judahítas sugiere matrimonios mixtos o identidad de clan compartida en el Néguev.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132515, 'spa', 'Gentilicio cenezeo', 'Designa al pueblo cenezeo o a individuos de ascendencia cenezea. Genesis 15:19 los enumera entre los pueblos cananeos en la promesa de tierra a Abraham. Numeros 32:12 y Josue 14:6, 14 identifican a Caleb como ''el cenezeo'', subrayando su origen no israelita pero su plena pertenencia a Israel por su fiel obediencia. El uso constante del articulo (הַקְּנִזִּי) lo marca como una designacion etnica reconocida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132516, 'spa', 'Posesiones, bienes, riqueza', 'Posesiones materiales, propiedades o riquezas vistas como resultado de una adquisición. Abarca ganado, bienes y toda propiedad mueble en los relatos patriarcales (Gn 34:23; 36:6; Jos 14:4), botín en la profecía de Ezequiel contra Gog (Ez 38:12-13) y la totalidad de las criaturas de Dios en Sal 104:24. Emparejado con בַּיִת en Sal 105:21, denota la riqueza íntegra del hogar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132519, 'spa', 'Adquisición, acto de compra', 'El acto o proceso de adquirir o comprar, con énfasis en la transacción más que en la posesión resultante. En Gn 31:18, מִקְנֵה קִנְיָנוֹ empareja el término con ganado para subrayar lo que Jacob había adquirido durante sus años con Labán —el obtener en sí—. Levítico 22:11 usa el constructo קִנְיַן כֶּסֶף, «adquisición por plata», especificando el medio de compra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132525, 'spa', 'especia aromática sagrada', 'El término identifica la corteza interior fragante usada como especia de alto valor en el antiguo Israel. En Éxodo 30:23, se especifica como uno de cuatro ingredientes aromáticos (junto con mirra, cálamo y casia) para hacer el aceite de santa unción—específicamente ''canela aromática'', enfatizando su cualidad odorífera. Los libros poéticos la usan metafóricamente: Proverbios 7:17 describe a una seductora perfumando su lecho con canela.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132526, 'spa', 'Anidar, hacer nido', 'Construir un nido, establecerse en un lugar seguro — usado literalmente de aves y figuradamente de habitación humana. El uso literal describe aves hallando hogar en los árboles (Sal 104:17; Ez 31:6). El figurado conlleva ironía: Jerusalén ''anidada entre cedros'' enfrenta destrucción (Jer 22:23), y Moab debe anidar como paloma en el precipicio ante el juicio (Jer 48:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132534, 'spa', 'El participio activo Qal usado como sustantivo agentivo', 'El participio activo Qal usado como sustantivo agentivo: un adivino, agorero o practicante de la adivinación. Es el uso más frecuente con 11 apariciones, presente en listas de practicantes prohibidos (Dt 18:10, 14), como título profesional (Jos 13:22 identifica a Balaam como הַקּוֹסֵם), y junto a sacerdotes y profetas como fuentes rivales de conocimiento (1 Sam 6:2; Is 3:2; 44:25). El español adivino selecciona un término técnico culturalmente específico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132536, 'spa', 'Una única aparición anómala en 1 Samuel 28', 'Una única aparición anómala en 1 Samuel 28:8 etiquetada como interjección con el significado de ''por favor.'' Esto casi con certeza refleja un error de etiquetado o asignación de lema en la base de datos morfológica y no un sentido genuino de קָסַם. La partícula נָא (la partícula hebrea de ruego) aparece en el mismo versículo y pudo haberse confundido con el verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132537, 'spa', 'El infinitivo constructo Qal funcionando como sustantivo verbal que denota el ac', 'El infinitivo constructo Qal funcionando como sustantivo verbal que denota el acto o la práctica de la adivinación en sí. Cinco apariciones se concentran en Ezequiel 21, donde el rey de Babilonia se detiene en la encrucijada ''para practicar adivinación'' (Ez 21:21) y su procedimiento adivinatorio se describe paso a paso. Miqueas 3:6 también usa el infinitivo para describir el cese de la actividad adivinatoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132538, 'spa', 'Formas verbales finitas (imperfecto, imperativo, consecutivo imperfecto) que des', 'Formas verbales finitas (imperfecto, imperativo, consecutivo imperfecto) que describen el acto concreto de adivinar en contextos narrativos. Saúl ordena a la médium de Endor que ''adivine para mí'' (1 Sam 28:8); Israel y Judá ''practicaron adivinación'' entre sus pecados acumulados (2 Re 17:17); las falsas profetisas ''no adivinarán más'' (Ez 13:23); los profetas ''adivinan por dinero'' (Miq 3:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132550, 'spa', 'Una forma nominal plural que se refiere a los productos o resultados de la adivi', 'Una forma nominal plural que se refiere a los productos o resultados de la adivinación — los pronunciamientos oraculares específicos obtenidos mediante la práctica adivinatoria. Aparece una vez en Deuteronomio 18:10; la forma plural קְסָמִים designa las adivinaciones como productos contables en lugar del agente o la práctica abstracta. El español adivinación y el inglés ''divinations'' pluralizan, apuntando a instancias concretas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132557, 'spa', 'Adivinación prohibida', 'El sentido dominante abarca la adivinación como práctica pagana o ilícita: predecir eventos o discernir lo oculto mediante técnicas ocultistas. Balaam lleva ''honorarios de adivinación'' (Nm 22:7), no hay adivinación eficaz contra Israel (Nm 23:23), y los falsos profetas pronuncian adivinaciones mentirosas (Ez 13:6). La ley deuteronómica la prohíbe expresamente (Dt 18:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132562, 'spa', 'Oráculo autoritativo', 'Una única aparición positiva en Pr 16:10, donde קֶסֶם se coloca en los labios de un rey: ''oráculo hay en los labios del rey; en juicio no prevaricará su boca.'' Aquí la palabra pasa de la hechicería prohibida a un pronunciamiento autoritativo, casi divinamente guiado. El español lo traduce distintivamente como ''oráculo'', mostrando la tensión semántica del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132566, 'spa', 'equipo profesional del escriba', 'La palabra se refiere específicamente al equipo profesional de un escriba—un estuche o tintero que contiene materiales de escritura. En Ezequiel 9:2-3, 11, la figura angelical que porta este implemento lo usa para marcar a quienes se lamentan por las abominaciones de Jerusalén, distinguiéndolos para preservación. El estuche de escriba funciona como insignia del oficio escribal y herramienta para registrar el juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132567, 'spa', 'Queila (ciudad de Judá) — Topónimo de una ciudad fortificada en la Sefela de Jud', 'Queila (ciudad de Judá) — Topónimo de una ciudad fortificada en la Sefela de Judá, cerca de la frontera filistea. David la liberó de un ataque filisteo pero huyó cuando Dios reveló que sus habitantes lo entregarían a Saúl (1 Sam 23:1–13). Figura entre las ciudades de Judá en Josué 15:44 y entre los distritos postexílicos que contribuyeron a la reconstrucción del muro de Nehemías (Neh 3:17–18). Posiblemente identificada con la actual Khirbet Qila.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132573, 'spa', 'Fuente, plato, bandeja — Fuente o bandeja poco profunda, siempre de plata en el ', 'Fuente, plato, bandeja — Fuente o bandeja poco profunda, siempre de plata en el uso atestiguado, que servía como vasija cúltica en el Tabernáculo. Enumerada entre los utensilios de la mesa para el pan de la Presencia (Éx 25:29; 37:16), y presentada doce veces como ofrenda de dedicación en Números 7 (cada una pesando 130 siclos). También mencionada entre los utensilios dispuestos sobre la mesa durante el transporte (Nm 4:7). El término está enteramente restringido al contexto ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132578, 'spa', 'solidificación literal o figurada', 'El término captura el proceso de líquidos solidificándose o quedando fijos en su lugar, sea literalmente o metafóricamente. El Cántico de Moisés lo usa para la posición sobrenatural de las aguas profundas como muros firmes durante el Éxodo. La imagen conmovedora de Job aplica el mismo verbo al desarrollo embrionario, comparando la formación divina de vida con leche cuajándose en queso. El indictamento de Sofonías describe a los habitantes de Jerusalén espiritualmente estancados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132582, 'spa', 'criatura de ruinas desoladas', 'El término designa una criatura salvaje característica de ruinas desoladas, apareciendo en tres oráculos de juicio. Isaías 14:23 pronuncia que Babilonia se volverá ''posesión del erizo'', mientras Isaías 34:11 la incluye entre los habitantes caóticos de la destrucción de Edom. Sofonías 2:14 similarmente visualiza esta criatura alojándose en las capitales arruinadas de Nínive. Sea erizo, puercoespín o avetoro, la función simbólica de inhabitabilidad permanece.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132584, 'spa', 'Cerrar, clausurar (Qal)', 'Cerrar o clausurar: el sentido dominante del Qal, que describe juntar la mano, la boca o la compasión para retener. Dt 15:7 advierte contra cerrar la mano (תִּקְפֹּץ) al hermano necesitado; Is 52:15 y Job 5:16 describen bocas cerradas de asombro o injusticia silenciada; Sal 77:9 pregunta si Dios ha ''clausurado'' sus misericordias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132586, 'spa', 'Ser recogido (Nifal)', 'Ser recogido o contraído: el Nifal reflexivo/pasivo en Job 24:24, donde los malvados ''son recogidos'' (יִקָּפְצוּן), contraídos y eliminados. El español ''son recogidos'' y otras versiones confirman el sentido pasivo de reunión, distinto del cierre activo del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132588, 'spa', 'Saltar, brincar (Piel)', 'Saltar, brincar, rebotar: el Piel intensivo en Cantares 2:8, donde el amado viene ''brincando'' (מְקַפֵּץ) sobre los montes. La misma contracción muscular que cierra una mano se convierte en energía elástica de salto. El español ''brincando'' y el francés ''bondissant'' captan este movimiento dinámico y gozoso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132591, 'spa', 'Fin, término temporal', 'Fin, término temporal: la conclusión o límite señalado de un período de tiempo. Aparece predominantemente en frases temporales como מִקֵּץ («al cabo de»), abarcando tanto duraciones definidas (Gn 8:6, «al cabo de cuarenta días»; Gn 41:1, «al cabo de dos años») como indefinidas (Gn 4:3, «andando el tiempo»). El uso profético se extiende al fin terminal de una nación o una vida (Am 8:2; Ez 7:2; Dn 9:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132603, 'spa', 'Extremo, punto más lejano', 'Extremo, punto más lejano: el límite espacial más remoto o el punto físico más distante de una extensión. Atestiguado solo tres veces, este sentido aparece donde el contexto exige geografía en vez de cronología. En 2 R 19:23 e Is 37:24, Senaquerib se jacta de haber alcanzado la «altura más remota» del Líbano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132611, 'spa', 'forma o extremidad', 'La palabra funciona en dos dominios semánticos. En contextos de construcción del templo (1 Reyes 6:25; 7:37), denota el corte preciso, forma o figura de objetos sagrados—las dimensiones labradas asegurando uniformidad. En Jonás 2:6, cambia a extremidad geográfica: ''las bases de los montes'', significando sus raíces sumergidas o fundamentos bajo el mar, representando las profundidades máximas de la tierra. Ambos sentidos implican límites o medidas definitivas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132612, 'spa', 'Cortar, raspar, cercenar', 'Cortar, raspar o remover por la fuerza, aplicado a superficies, pueblos o miembros. El Hifil en Levitico 14:41,43 se especializa como raspado de paredes durante la purificacion ritual, mientras que el Qal y el Piel se extienden a la destruccion de pueblos (Hab 2:10; 2 R 10:32) y a la vivida metafora de cortarse los pies en Proverbios 26:6.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132613, 'spa', 'Extremo físico, borde o punta', 'Extremo físico, borde o punta: el extremo físico, punta, borde o límite de un objeto concreto o área delimitada (44 apariciones). Incluye la punta de un bastón (Jue 6:21; 1 S 14:27), el borde de una cortina o tablón (Éx 26:28; 36:33), el límite de un campamento (Éx 13:20; 16:35; Nm 11:1) y la boca de un conducto (Is 7:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132614, 'spa', 'Confín de un territorio o de la tierra', 'Confín de un territorio o de la tierra: la extensión más remota, el límite extremo o la parte más alejada de un territorio, nación o de la tierra misma (38 apariciones). Frecuentemente en la construcción מִקְצֵה הָאָרֶץ («desde el extremo de la tierra», Dt 28:49; Is 5:26). Este sentido escala desde bordes locales hasta horizontes cósmicos: la misma palabra describe el borde de un campo (Gn 23:9) y los confines de los cielos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132616, 'spa', 'Fin temporal de un período', 'Fin temporal de un período: el fin temporal de un período, con el significado de «después de» o «al cabo de» una duración especificada (10 apariciones). Siempre en la construcción fija מִקְצֵה/מִקֵּץ + sustantivo temporal: «al cabo de cuarenta días» (Gn 8:6), «al cabo de tres años» (Dt 14:28), «al cabo de tres días» (Jos 3:2; 9:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132640, 'spa', 'Fin o limite negado', 'Un fin o limite, siempre negado en la frase ''no hay fin de'', para expresar cantidad inagotable. Isaias 2:7 lo usa dos veces para la riqueza y los carros interminables de Juda; Nahum lo aplica al botin de Ninive (2:9), a los cadaveres innumerables (3:3) y a la fuerza militar sin limites (3:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132641, 'spa', 'Las extremidades o puntas concretas de objetos físicos, predominantemente en las', 'Las extremidades o puntas concretas de objetos físicos, predominantemente en las instrucciones del tabernáculo y las vestiduras sacerdotales. Éxodo 25:18-19 posiciona los querubines en los dos ''extremos'' del propiciatorio; Éxodo 26:4 y 28:7, 23-26 ubican bordes de cortinas, tirantes del efod y cadenas del pectoral. Domina el plural constructo con sufijos pronominales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132645, 'spa', 'Las extremidades remotas o los confines más lejanos de un territorio, una tierra', 'Las extremidades remotas o los confines más lejanos de un territorio, una tierra o la tierra misma. Job 28:24 declara que Dios mira ''hasta los confines de la tierra''; Salmo 19:6 traza el circuito del sol ''hasta sus extremos''; Isaías 40:28 y 41:5 invocan los ''confines de la tierra'' como testigos de la soberanía incansable de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132653, 'spa', 'Bordes o límites — la línea fronteriza exterior de algo, más que su punto termin', 'Bordes o límites — la línea fronteriza exterior de algo, más que su punto terminal. Job 26:14 reflexiona: ''estos son solo los bordes de sus caminos,'' refiriéndose a los márgenes más externos de las obras de Dios que podemos percibir. Este matiz raro distingue la frontera del punto final arquitectónico del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132655, 'spa', 'límites geográficos extremos', 'La palabra se refiere a los límites más distantes de la tierra o territorio. En Salmos 48:10 y 65:5, ''los confines de la tierra'' es una expresión estándar para todo el mundo habitado donde el nombre de Dios y sus actos justos son conocidos—un merismo que sugiere completitud de extremo a extremo. Isaías 26:15 lo usa de manera diferente: ''Has extendido todos los límites de la tierra'', donde significa las fronteras ampliadas o los confines del territorio israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132656, 'spa', 'planta de neguilla', 'Este término agrícola identifica la planta Nigella sativa y sus semillas, apareciendo tres veces en la parábola agrícola de Isaías. El versículo 25 menciona su siembra junto con otros cultivos, mientras que el versículo 27 describe dos veces su método de cosecha: el comino negro se golpea con una vara en lugar de trillarse con trineos o ruedas. La técnica agrícola cuidadosa refleja el trato precisamente calibrado de Dios con Su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132657, 'spa', 'Gobernante, magistrado', 'Gobernante civil o político que ejerce autoridad sobre un pueblo. Isaías se dirige a líderes corruptos como ''gobernantes de Sodoma'' (Is 1:10), y Miqueas acusa a los ''gobernantes de la casa de Israel'' que pervierten la justicia (Mi 3:1, 9). En Is 3:6-7, la búsqueda desesperada de alguien dispuesto a ser qāṣīn muestra la gravedad del cargo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132659, 'spa', 'Comandante, capitán', 'Comandante militar o capitán que dirige tropas en el campo de batalla. Los comandantes de Josué ponen sus pies sobre los cuellos de reyes conquistados (Jos 10:24), y Jefté es nombrado ''cabeza y comandante'' sobre Galaad (Jue 11:6, 11). Daniel 11:18 emplea el término para un comandante que vuelve contra otro poder.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132670, 'spa', 'Cosecha (acto/estación)', 'Cosecha (acto/estación): la estación, actividad o producto de la siega de cultivos de grano, funcionando simultáneamente como marcador calendárico, realidad agrícola y metáfora teológica. Como estación: anclada en Gn 8:22 («siembra y cosecha»), estructura el calendario festivo (Éx 23:16 «fiesta de la cosecha»; Éx 34:22 «cosecha de trigo»). Como labor y producto: se contratan trabajadores para ella (1 S 8:12) y se dejan espigas para los necesitados. Proféticamente, la cosecha se convierte en poderosa metáfora del juicio divino (Jer 8:20; Os 6:11; Jl 3:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132692, 'spa', 'Ramas de un arbol', 'Ramas o ramaje de un arbol, usado colectivamente para la parte frondosa superior. Job lo emplea figuradamente: la rama del impio se seca mientras sus raices se marchitan (18:16), la del justo se mantiene fresca con rocio (29:19), y un arbol talado puede retonar (14:9). El Salmo 80:11 e Isaias 27:11 confirman este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132695, 'spa', 'Estar airado, enojado o disgustado — el sentido estativo básico del Qal, usado t', 'Estar airado, enojado o disgustado — el sentido estativo básico del Qal, usado tanto para la ira divina como la humana. Con 28 apariciones, es el significado predeterminado del verbo; aparece cuando Dios se aíra contra la rebelión de Israel (Dt 1:34; Is 57:16-17; 64:5, 9), cuando el copero y el panadero del faraón caen en desgracia (Gn 40:2; 41:10), cuando Naamán se aleja furioso de Eliseo (2 R 5:11) y cuando el rey Asuero se enfurece (Est 1:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132697, 'spa', 'Provocar a ira — la raíz causativa Hifil, donde el sujeto gramatical hace que ot', 'Provocar a ira — la raíz causativa Hifil, donde el sujeto gramatical hace que otro (normalmente Dios) se airé. Las cinco apariciones se concentran en el recuerdo de Moisés sobre las provocaciones de Israel en el desierto (Dt 9:7, 8, 22) y en resúmenes retrospectivos del pecado nacional (Sal 106:32; Zac 8:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132713, 'spa', 'Enfurecerse — la raíz reflexivo-intensiva Hitpael, que expresa una furia elevada', 'Enfurecerse — la raíz reflexivo-intensiva Hitpael, que expresa una furia elevada y autoconsumidora que va más allá del simple desagrado. Solo una aparición clara: Isaías 8:21, donde un pueblo desesperado y hambriento ''se enfurecerá y maldecirá a su rey y a su Dios.'' El Hitpael aporta la intensificación reflexiva que distingue esta rabia de la ira ordinaria del Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132719, 'spa', 'Ira divina intensa o indignación, típicamente provocada por la violación del pac', 'Ira divina intensa o indignación, típicamente provocada por la violación del pacto o la transgresión ritual, y que resulta en un castigo devastador. La literatura sacerdotal la trata como una fuerza cuasi-física que la fidelidad levítica debe prevenir (Nm 1:53; 18:5). Estalla en la rebelión de Coré (Nm 16:46), la transgresión de Acán (Jos 22:20), y explica la necesidad del exilio (2 Cr 29:8; 36:16). La expresión de Isaías ''con ira desbordante escondí mi rostro de ti por un instante'' (Is 54:8) captura su ferocidad repentina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132734, 'spa', 'Rapar las sienes — Uso especializado del Qal pasivo restringido a Jeremías (9', 'Rapar las sienes — Uso especializado del Qal pasivo restringido a Jeremías (9:26, 25:23, 49:32), que describe a pueblos que tienen las sienes rapadas o recortadas, una práctica cosmética o de duelo asociada con tribus del desierto arábigo. La frase hebrea קְצוּצֵי פֵאָה se traduce como ''los de sienes rapadas'', destacando que no es un simple corte sino una marca cultural distintiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132735, 'spa', 'Cortar, cercenar — El sentido activo primario', 'Cortar, cercenar — El sentido activo primario: cortar o cercenar de manera decisiva, ya sean miembros (los pulgares y dedos gordos de Adoni-bezec, Jue 1:6), paneles de bronce (2 R 16:17) o hilos de oro batidos para trabajo textil (Éx 39:3). Apunta a la remoción de una parte de un todo mediante una sola acción deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132740, 'spa', 'Cortar en pedazos, despedazar — Sentido intensivo del Piel que enfatiza la fragm', 'Cortar en pedazos, despedazar — Sentido intensivo del Piel que enfatiza la fragmentación más que el simple cercenamiento: cortar en pedazos o romper. En 2 R 24:13 Nabucodonosor corta los utensilios de oro del templo, y en 2 Cr 28:24 Acaz destroza los utensilios de la casa de Dios. El cambio es de un corte limpio a una destrucción por fragmentación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132745, 'spa', 'Ser cortado (pasivo) — Participio pasivo del Pual que denota el estado de haber ', 'Ser cortado (pasivo) — Participio pasivo del Pual que denota el estado de haber sido cortado o cercenado. Jueces 1:7 describe a Adoni-bezec recordando a setenta reyes con pulgares y dedos gordos ya ''cortados'', el resultado pasivo completado de la acción del sentido 1. El carácter perfectivo y estativo de esta forma lo distingue del corte activo y del recorte cosmético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132748, 'spa', 'Ser corto, ser insuficiente', 'Ser corto, ser insuficiente. El sentido básico en Qal de ser físicamente corto, insuficiente o inadecuado en extensión o alcance. El uso teológico clásico empareja este verbo con la ''mano'' de Dios para preguntar si el poder divino se queda corto — ''¿Acaso se ha acortado la mano del SEÑOR?'' (Isa 50:2; 59:1). Proverbios 10:27 lo aplica al acortamiento de la vida, mientras que Isaías 28:20 emplea la imagen de algo demasiado corto para cubrirse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132750, 'spa', 'Impacientarse, hastiarse', 'Impacientarse, hastiarse. Un sentido idiomático en Qal donde el alma (néfesh) o el espíritu (rúaj) ''se acorta'', expresando impaciencia, frustración o agotamiento emocional. La construcción hebrea qatsrá nafsho es una metáfora corporal: el ser interior se constriñe y no puede soportar más. Pasajes clave incluyen el hastío de Israel en el desierto (Núm 21:4) y el agotamiento de la paciencia de Dios con su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132756, 'spa', 'Acortar (causativo, Hifil)', 'Acortar (causativo, Hifil). El sentido causativo en Hifil: acortar o abreviar activamente algo, especialmente la duración de la vida o la juventud. En el Salmo 89:45, el salmista lamenta que Dios ''acortó los días de su juventud'', usando el tronco causativo para asignar la agencia al actor divino en este salmo de lamento real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132761, 'spa', 'Abreviar (intensivo, Piel)', 'Abreviar (intensivo, Piel). El sentido intensivo en Piel: abreviar de manera decisiva y enfática. En el Salmo 102:23, el hablante afligido protesta que Dios ''acortó mis días'' en medio de la vida. El tronco intensivo transmite una reducción más enérgica y deliberada que el simple Qal, reforzando el tono de queja urgente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132762, 'spa', 'Cortar y recoger una cosecha en pie durante la siega, ya sea literal o figuradam', 'Cortar y recoger una cosecha en pie durante la siega, ya sea literal o figuradamente. El sentido literal domina en la legislación de la Torá sobre el derecho de espigadura (Lv 19:9; 23:22; Dt 24:19) y en narraciones de cosecha (Rt 2:9; 1 S 6:13; 8:12). La extensión figurada —cosechar lo que se ha sembrado— aparece en textos proféticos y sapienciales (Os 10:12; Jer 12:13; Job 4:8; Pr 22:8). El Salmo 126:5 cristaliza la metáfora: ''los que siembran con lágrimas, con regocijo segarán.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132791, 'spa', 'Corto, limitado', 'Corto, siempre en estado constructo con otro sustantivo para generar sentidos figurados: ''corto de mano'' (debil), ''corto de espiritu'' (impaciente) o ''corto de dias'' (efimero). En Proverbios 14:17,29 describe al iracundo; en 2 Reyes 19:26 e Isaias 37:27 senala la impotencia de las naciones; en Job 14:1 expresa la brevedad de la vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132792, 'spa', 'Parte de (partitivo)', 'Uso partitivo: ''parte de, algunos de'', indicando un subconjunto indefinido de un todo mayor. Daniel 1:2 dice que Dios entregó ''parte de los utensilios'' del templo, y Nehemías 7:70 registra que ''algunos de los jefes de familias'' contribuyeron a la obra. Este uso de מִקְצָת con min es característico del hebreo bíblico tardío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132794, 'spa', 'Fin, extremo', 'Sentido espacial y temporal: ''fin, extremo, borde''. Se usa para las esquinas del enrejado del altar (Éx 38:5; cf. 37:8; 39:4), los confines de la tierra (Sal 65:9) y puntos temporales finales (''al cabo de diez días'', Dn 1:15). El árabe nihayah (نِهَايَة) confirma la función demarcadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132797, 'spa', 'conclusión temporal o porción', 'La palabra aramea designa ya sea conclusión temporal o porción fraccionaria. Daniel 4:29 y 4:34 lo usan con ''al fin de'' para marcar cuándo concluyen períodos de meses—el momento cuando expiró el año de advertencia de Nabucodonosor y cuando llegó su restauración. Daniel 2:42 lo emplea espacial/constitucionalmente: ''parte del reino será...'' describiendo la composición mixta de los pies de la estatua profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132798, 'spa', 'frescura física o temperamental', 'El término caracteriza frescura bienvenida en contextos tanto físicos como temperamentales. El sentido literal aparece en Jeremías 18:14 (''aguas frías que fluyen'') y Proverbios 25:25 (''agua fría al alma sedienta''), donde la frescura refrescante representa confiabilidad y revitalización. La extensión figurada en Proverbios 17:27 (Ketiv) describe temperamento personal: ''fresco de espíritu'' indica autocontrol compuesto, equilibrio emocional que no se acalora fácilmente con ira o agitación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132803, 'spa', 'llamar, convocar, nombrar', 'Sentido nuclear: llamar, convocar o nombrar (575x). El árabe da''a, el coreano 부르다 y el suajili kuita convergen aquí. Gn 2:19 (Adán nombrando a los animales), Gn 22:11 (el ángel llamando a Abraham) y Gn 20:8 (Abimélec convocando a sus siervos) ilustran la amplitud: desde conferir identidad hasta reclamar atención. Es el centro semántico del que irradian las demás acepciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132807, 'spa', 'clamar en angustia', 'Clamar en aflicción o apelación urgente (69x). El coreano 부르짖다/외치다 y el español clamar/gritar lo distinguen del llamado neutro. Jue 15:18 (Sansón clamando de sed) y Jue 16:28 (su oración final) revelan la cualidad vocal desesperada. El clamor se dirige típicamente hacia arriba — a Dios — o hacia afuera en señal de alarma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132829, 'spa', 'ser llamado, ser nombrado', 'Pasivo: ser llamado o nombrado (Nifal/Pual, 30x). El árabe du''iya, el coreano 불리다 y el suajili -itwa rinden consistentemente la voz pasiva. Gn 48:6 (''serán llamados por el nombre de sus hermanos'') y Dt 28:10 (''todos los pueblos verán que eres llamado por el nombre de YHWH'') muestran el acto de nombrar como conferencia de identidad desde fuera del individuo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132833, 'spa', 'proclamar, anunciar', 'Proclamación pública formal o anuncio solemne (32x). El coreano 선포하다 y el suajili kutangaza marcan el registro oficial y autoritativo. Éx 33:19 y 34:5-6 (Dios proclamando su propio nombre y atributos) muestran el peso teológico de esta acepción. Lv 23:2 (proclamar las asambleas sagradas) ilustra su función ritual-administrativa en la vida israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132839, 'spa', 'leer, recitar en voz alta', 'Leer un texto escrito en voz alta o recitar de un rollo (24x). El árabe qara''a — raíz de ''Corán'' — conserva este significado específico. El coreano 읽다 y el suajili kusoma lo distinguen del llamado oral. Éx 24:7 (Moisés leyendo el Libro de la Alianza), Dt 17:19 y Jos 8:34 (Josué leyendo la Torá) lo muestran como acto litúrgico público.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132887, 'spa', 'invitar, convidar', 'Invitar o convocar a un banquete, sacrificio o reunión social (9x). El árabe mad''uww (''invitado'') y el coreano 초대하다 (''invitar'') aíslan este sentido de hospitalidad social. Éx 34:15 (ser invitado a comer sacrificios idolátricos) y 1 S 9:13, 22, 24 (Samuel invitando a Saúl al banquete sacrificial) sitúan el verbo en contextos conviviales de comida y comunión compartidas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132981, 'spa', 'El sentido principal del infinitivo constructo Qal liqra''t', 'El sentido principal del infinitivo constructo Qal liqra''t: ir al encuentro de alguien, funcionando casi preposicionalmente como ''hacia.'' Usado abrumadoramente en contextos militares y sociales: salir al encuentro de un rey, un ejército o un visitante (1 S 4:1; 9:14; 13:10). El carácter intencional y direccional define este uso más frecuente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132984, 'spa', 'Eventos, calamidades o circunstancias que le sobrevienen a una persona, frecuent', 'Eventos, calamidades o circunstancias que le sobrevienen a una persona, frecuentemente con matices de infortunio o juicio divino. Jacob teme que le ''sobrevenga'' daño a Benjamín (Gn 42:4, 38); Moisés advierte sobre lo que le ''acontecerá'' a Israel en los últimos días (Gn 49:1; Dt 31:29). Se pasa del encuentro espacial a la ocurrencia temporal, captando la cualidad pasiva e involuntaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132985, 'spa', 'Hifil causativo', 'Hifil causativo: hacer que algo le sobrevenga a alguien, traer calamidad sobre otro. Jeremías 32:23 acusa al pueblo de desobediencia, y Dios ''hizo venir todo este mal sobre ellos.'' Esta única aparición extiende el sentido de ''sobrevenir'' hacia la orquestación divina activa de consecuencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132991, 'spa', 'Infinitivo absoluto Nifal usado adverbialmente para expresar casualidad o accide', 'Infinitivo absoluto Nifal usado adverbialmente para expresar casualidad o accidente: ''por casualidad'' o ''según aconteció.'' En 2 Samuel 1:6 el amalecita dice ''acontecí estar en el monte Gilboa.'' Muestra el desplazamiento semántico del verbo de encuentro al adverbio de contingencia, un caso notable de blanqueamiento semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132996, 'spa', 'Nifal recíproco', 'Nifal recíproco: dos partes que se encuentran mutuamente, implicando reciprocidad o lo inesperado. En Éxodo 5:3 Dios ''se encontró'' con Moisés y Aarón, y en 2 Samuel 18:9 Absalón ''se encontró'' con los siervos de David. La voz media del Nifal sugiere un encuentro desde ambos lados, distinguiéndolo del movimiento unidireccional del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (132998, 'spa', 'Nifal imperfecto con sentido locativo y pasivo', 'Nifal imperfecto con sentido locativo y pasivo: ser encontrado o hallarse en un lugar. Deuteronomio 22:6 habla de un nido de ave que ''se encuentre'' en el camino. Este uso estativo enfatiza la presencia del objeto esperando ser descubierto, más que el movimiento de ningún agente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133001, 'spa', 'Un probable solapamiento homográfico con qara'' (H7121, ''llamar'')', 'Un probable solapamiento homográfico con qara'' (H7121, ''llamar''): Nifal ''ser llamado o nombrado.'' En 2 Samuel 20:1 un hombre llamado Seba ''se encontraba allí'' o, más probablemente según esta etiquetación, ''fue llamado'' por nombre. Esto puede representar un artefacto de etiquetado más que un verdadero sentido de H7122.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133004, 'spa', 'Leer en voz alta', 'Leer en voz alta, especialmente un documento oficial o inscripción. Las formas Pe''al y Pe''il dominan Daniel 5, donde la escritura en la pared debe ser leída (Dn 5:7-8, 15-17), y Esdras 4:18, 23, donde una carta real ''fue leída'' ante el rey. El español ''leer/lea'' marca esto como desciframiento y ejecución oral de texto escrito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133006, 'spa', 'Proclamar, clamar', 'Clamar o proclamar públicamente con autoridad. El participio Pe''al en Daniel 3:4 describe a un heraldo ''clamando con fuerza'', y Daniel 4:14 presenta a un vigilante proclamando desde el cielo. El español ''proclamaba/gritó'' trata esto como discurso público autoritativo. Daniel 5:7 conecta ambos sentidos: el rey proclama que quien pueda leer la escritura será recompensado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133010, 'spa', 'Ser convocado', 'Ser convocado o llamado oficialmente (Hitpe''el pasivo-reflexivo). Aparece una sola vez en Daniel 5:12, donde la reina recomienda que Daniel ''sea llamado''. Esta forma extiende el sentido de habla pública de la raíz al ámbito de la convocatoria oficial, marcando la transición de proclamar a citar formalmente a una persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133013, 'spa', 'salir al encuentro', 'Ir hacia alguien para encontrarse con esa persona, ya sea en saludo, bienvenida, confrontación o batalla. Aparece 99 veces, mayoritariamente como el infinitivo constructo liqra''t que funciona como preposición. Abarca encuentros gozosos (Éx 18:7), enfrentamientos militares (1 Sam 17:48) y recepciones formales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133036, 'spa', 'frente a, enfrente de', 'Correspondencia u oposición espacial: colocar algo enfrente de o de cara a su contraparte. En Génesis 15:10, Abram dispone las mitades de los animales del pacto cada una frente a su par. El sentido conserva la idea raíz de encuentro como alineación física más que como relación interpersonal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133046, 'spa', 'ofrecer, presentar ritualmente', 'El sentido cúltico dominante en Hifil: presentar un sacrificio, ofrenda vegetal o animal a Yahvé según el ritual prescrito. Levítico emplea esta forma abrumadoramente (Lv 1:13-14; 3:3-9). La evidencia multilingüe es llamativa: el árabe yuqarribu en forma II refleja exactamente el causativo hebreo, mientras que el coreano 드리다 y el hindi चढ़ाना seleccionan vocabulario dedicado a la ofrenda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133048, 'spa', 'hacer acercar, traer', 'Causativo Hifil en contextos no cúlticos: hacer que alguien o algo se acerque físicamente. Se distingue del sentido 1 porque no hay sacrificio en vista; más bien, Moisés presenta a los levitas ante la congregación (Nm 8:9-10) o el ejército de Faraón se aproxima (Éx 14:10). El español lo distingue bien: hizo acercar frente a ofrecer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133053, 'spa', 'acercarse, aproximarse', 'El significado intransitivo básico del Qal: acercarse, venir cerca, aproximarse a una persona, lugar o situación. Este es el sentido espacial raíz del que se desarrollan todos los demás. Se encuentra en la narrativa (Lv 9:5-8, Moisés ordenando a Aarón aproximarse al altar) y en el discurso profético por igual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133096, 'spa', 'estar cerca, estar próximo', 'Sentido estativo del Qal: estar cerca, estar a la mano, describiendo un estado de proximidad más que de movimiento. A menudo temporal: ''el día está cerca'' (Lm 4:18) o ''el año de la remisión está próximo'' (Dt 15:9). Solo 4 apariciones, pero constituyen una distinción semántica importante frente al ''acercarse'' activo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133109, 'spa', 'acercar intensivamente', 'Piel intensivo: un acercamiento deliberado y enfático, usado con moderación para momentos de peso teológico. En Job 31:37 Job declara que se acercaría a Dios como un príncipe; en Sal 65:4 es Dios quien activamente acerca al escogido para habitar en sus atrios. Solo 6 apariciones, cada una con carga teológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133170, 'spa', 'acercarse para juicio', 'Una aparición única en Éx 22:8 donde el sentido es ambiguo o transicional: el contexto describe la comparecencia ante Dios o los jueces para adjudicación judicial. Las traducciones tratan el vocablo como simple acercamiento, pero el escenario forense podría justificar un sub-sentido jurídico especializado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133207, 'spa', 'Acercarse, aproximarse', 'Aproximación física o acercamiento a una persona o lugar (Qal). Se traduce de modo consistente como movimiento hacia alguien. Se usa cinco veces en Daniel para acercarse a reyes, intérpretes y al foso de los leones (Dn 3:8, 26; 6:12, 20; 7:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133209, 'spa', 'Ofrecer sacrificio', 'Ofrecer o presentar sacrificio en el altar (Piel/Hifil causativo). La extensión cultual de «acercar»: los animales de sacrificio y las ofrendas son llevados al altar de Dios. El español «ofrecieron/ofrecerás» confirma el registro sacrificial. Las tres ocurrencias se concentran en el contexto de restauración del templo en Esdras (Esd 6:10, 17; 7:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133211, 'spa', 'Presentar ante un superior', 'Presentar a una persona ante un superior (Hifil). Uso singular y teológicamente denso en Dn 7:13, donde el Hijo del Hombre es llevado ante el Anciano de Días. El español lo traduce pasivamente como «fue llevado», destacando la escolta reverencial más que el mero desplazamiento físico. Este sentido conlleva matices de investidura y audiencia real, distintos tanto del acercamiento ordinario como del sacrificio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133215, 'spa', 'Batalla, guerra', 'Batalla, guerra, conflicto armado: préstamo arameo (cognado del siríaco qrav) empleado en registros elevados y poéticos. Paralelo a מִלְחָמָה («guerra») en Job 38:23 y Sal 144:1, pero preferido en Salmos, Job, Eclesiastés y Zacarías antes que en prosa histórica. La expresión יוֹם קְרָב («día de batalla», Zac 14:3; Sal 78:9) designa un enfrentamiento militar decisivo, mientras que כְּלֵי קְרָב («armas de guerra», Ecl 9:18) denota armamento bélico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133222, 'spa', 'medio, en medio de', 'El sentido preposicional dominante: medio, entre, en el centro de una entidad colectiva. Con 165 apariciones, este vocablo con be- o min- sitúa algo espacial o socialmente dentro de un grupo, ciudad, nación o territorio. Dios promete andar en medio del campamento (Dt 23:14); los idólatras son purgados de en medio de Israel (Dt 13:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133225, 'spa', 'entrañas, vísceras', 'Los órganos internos literales o entrañas de un animal, especialmente en contextos sacrificiales y alimentarios. Se halla 22 veces, concentrado en Éxodo y Levítico, donde las entrañas del holocausto deben ser lavadas (Éx 29:13, 17; Lv 1:9, 13) y el cordero pascual debe asarse entero con sus vísceras (Éx 12:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133230, 'spa', 'interior, ser íntimo', 'El interior psicológico-espiritual de una persona: ser íntimo, corazón, yo interior. En 40 apariciones el vocablo se desplaza de la geografía comunitaria a la interioridad personal: Sara ríe ''dentro de sí'' (Gn 18:12), el corazón de Nabal muere ''dentro de él'' (1 Sam 25:37) y el salmista clama: ''Bendice, alma mía, al Señor, y todo lo que está dentro de mí'' (Sal 103:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133283, 'spa', 'Que se acerca', 'Que se acerca o se aproxima, adjetivo verbal de qarab. Predicativamente describe movimiento progresivo, como Goliat avanzando sobre David (1 S 17:41) o soldados cerrando filas para la batalla (Dt 20:3). Sustantivamente con artículo, designa a quienes se acercan al santuario para el servicio sacerdotal (Nm 1:51; Ez 40:46; 45:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133290, 'spa', 'Ofrenda, oblación (qorbán)', 'Ofrenda, oblación (qorbán): el término levítico general para cualquier don sacrificial u oblación acercada a Dios, derivado de la raíz q-r-b («acercarse»). Abarca holocaustos de animales (Lv 1:2-3), ofrendas de grano (Lv 2:1), primicias (Lv 2:12) y dedicaciones de metales preciosos (Nm 31:50). La palabra enmarca la adoración como un acto de aproximación: acercarse a la presencia divina con un don consagrado. Jesús se refiere directamente al término en Mr 7:11, donde el voto de qorbán se había convertido en un tecnicismo legal para evadir el deber filial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133303, 'spa', 'Hacha para cortar', 'Hacha empleada para talar arboles y trabajar la madera, en contextos tanto literales como militares. Jueces 9:48 muestra a Abimélec cortando ramas para un asedio; 1 Samuel 13:20-21 incluye las hachas entre herramientas que Israel no podia afilar sin permiso filisteo; el Salmo 74:5 describe la destruccion del templo y Jeremias 46:22 compara al invasor con lenadores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133304, 'spa', 'frío atmosférico', 'Frío o frialdad como condición climática: el hielo invernal, las noches gélidas o los vientos helados. Nahúm 3:17 lo asocia a un día específico, Proverbios 25:20 lo emplea en un proverbio sobre la insensibilidad, Job 24:7 retrata la exposición de los pobres sin refugio, y Salmo 147:17 lo presenta como instrumento del poder de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133305, 'spa', 'El uso más común describe un evento que acontece o le sucede a alguien, frecuent', 'El uso más común describe un evento que acontece o le sucede a alguien, frecuentemente con un sufijo pronominal que marca a la persona afectada. Rut 2:3 lo capta bellamente — ''su acontecer aconteció en el campo de Booz'' — donde el narrador usa la construcción cognada para subrayar la coincidencia providencial. Las glosas multilingües convergen en verbos de ocurrencia: el español acontece, el francés arriver y el alemán geschehen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133306, 'spa', 'En la raíz Nifal el verbo pasa del acontecer impersonal al encuentro personal', 'En la raíz Nifal el verbo pasa del acontecer impersonal al encuentro personal. Dios ''se encuentra'' con Balaam repetidamente en Números 23 (vv. 3-4, 15-16), y Moisés le dice a Faraón que ''el Dios de los hebreos nos ha encontrado'' (Éx 3:18). El español se encontró y la construcción reflexiva destacan la naturaleza recíproca o divinamente iniciada de estos encuentros — no mero azar sino convergencia deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133312, 'spa', 'El Hifil causativo extiende la raíz al ámbito de la orquestación y la designació', 'El Hifil causativo extiende la raíz al ámbito de la orquestación y la designación. El siervo de Abraham pide a Dios que ''haga acontecer delante de mí'' a la mujer indicada (Gn 24:12), mientras que Números 35:11 lo usa para designar ciudades de refugio — literalmente haciendo que el fugitivo ''encuentre'' asilo. El español designaréis para el pasaje de las ciudades de refugio muestra cómo los traductores pasan naturalmente del encuentro a la asignación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133322, 'spa', 'Una única aparición en Qal con objeto personal directo en Deuteronomio 25', 'Una única aparición en Qal con objeto personal directo en Deuteronomio 25:18 — Amalec ''te encontró'' en el camino y atacó a los rezagados. A diferencia del sentido impersonal de ''acontecer,'' el enfoque aquí está en el encuentro físico hostil entre pueblos. La inmediatez del sufijo pronominal (''te encontró'') y el contexto militar distinguen este sentido del más pasivo ''suceder'' del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133324, 'spa', 'enmaderar, poner vigas', 'Colocar vigas o proveer una estructura con maderos: término técnico de carpintería en Piel. Tres de cinco apariciones se concentran en la reconstrucción de Nehemías (2:8; 3:3; 3:6). Segunda Crónicas 34:11 lo usa para la restauración del templo. El uso más poético es Salmo 104:3, donde Dios enmaderara sus aposentos celestiales sobre las aguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133326, 'spa', 'Cercano, próximo (espacial)', 'Cercano, próximo (espacial): físicamente cerca o próximo en el espacio, describiendo la proximidad de lugares, ciudades, caminos o personas respecto a un punto de referencia. Éx 13:17 señala que Dios no condujo a Israel por el camino cercano, y Gn 19:20 presenta a Lot rogando huir a una ciudad que está cerca. A menudo emparejado con su antónimo רָחוֹק («lejos») para expresar totalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133332, 'spa', 'Acercarse a Dios', 'Acercarse a Dios: los admitidos a la presencia cúltica de Dios, describiendo a sacerdotes o adoradores santificados que se acercan en el servicio sagrado. Lv 10:3 declara «por medio de los que se acercan a mí me mostraré santo», inmediatamente después del fuego extraño de Nadab y Abiú. Ez 42:13 y 43:19 reservan este lenguaje para los sacerdotes sadoquitas. La raíz espacial adquiere un peso numinoso: la proximidad se convierte en acceso sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133333, 'spa', 'Pariente, allegado, prójimo', 'Pariente, allegado, prójimo: un pariente, familiar, vecino o asociado cercano, usado sustantivamente con sufijos pronominales. Éx 32:27 ordena «matad cada uno a su cercano», es decir, a su pariente. Job 19:14 lamenta que sus cercanos lo han abandonado. El hebreo traza el mismo camino semántico de la proximidad física a la cercanía relacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133337, 'spa', 'Cercano en el tiempo, pronto', 'Cercano en el tiempo, pronto: próximo en el tiempo, señalando inminencia o algo reciente. Ez 7:7-8 advierte «el día está cercano»: el juicio se avecina. Dt 32:17 describe dioses que «vinieron de cerca», es decir, de reciente aparición. Este sentido temporal suele traducirse como «pronto» o «a las puertas».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133359, 'spa', 'Rasurar por duelo', 'Hacerse calvo, rasurar la cabeza como rito de duelo — remoción deliberada del cabello que expresa luto por los muertos o por calamidad nacional. Prohibido para los sacerdotes (Lev 21:5), pero los profetas lo invocan: Miqueas lo ordena por los hijos exiliados (Miq 1:16). Abarca desde el acto físico de rasurar hasta el gesto simbólico de aflicción visible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133365, 'spa', 'Hielo, escarcha', 'Hielo o escarcha: agua congelada como fenómeno meteorológico natural. Se usa en Génesis 31:40 para la escarcha que soportó Jacob, y en la poesía sapiencial: Job 37:10 (agua congelada por el soplo de Dios), Job 38:29 (el vientre del hielo como misterio divino) y Salmo 147:17 (Dios arrojando hielo como pedazos). Ezequiel 1:22 lo aplica a la extensión celestial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133370, 'spa', 'El nombre propio Qóraj, que identifica a múltiples personajes del AT y sus desce', 'El nombre propio Qóraj, que identifica a múltiples personajes del AT y sus descendientes. El levita rebelde de Números 16 domina el perfil del nombre (Nm 16:1-49; 26:9-11; 27:3), pero los ''hijos de Coré'' que sobrevivieron se convirtieron en un gremio levítico de músicos del templo cuyo nombre aparece en los encabezados de once salmos (Sal 42, 44-49, 84-85, 87-88) — un notable arco de redención desde la rebelión del padre hasta la adoración de los hijos. El nombre también aparece entre los descendientes de Esaú como jefe de clan edomita (Gn 36:5, 14, 16, 18) y como ''hijo'' judahita de Hebrón (1 Cr 2:43).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133375, 'spa', 'condición de calvicie', 'La palabra designa la condición de tener una cabeza sin pelo. En la legislación de pureza levítica, aparece en descripción clínica: si el cabello de alguien se cae en la coronilla o parte posterior de la cabeza, es simplemente calvo y permanece limpio (a menos que se desarrolle enfermedad de la piel). El uso narrativo es bastante diferente: jóvenes lanzando ''¡Sube, calvo!'' a Eliseo convirtieron este término descriptivo en burla—posiblemente ridiculizando su apariencia física o usando calvicie como insulto simbólico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133376, 'spa', 'El nombre propio Carea (קָרֵחַ, ''calvo''), que identifica al padre de Johanán ben', 'El nombre propio Carea (קָרֵחַ, ''calvo''), que identifica al padre de Johanán ben Carea, destacado líder militar del remanente judío posterior a la destrucción. BDB confirma el significado ''calvo''. El nombre aparece exclusivamente en 2 Reyes 25:23 y Jeremías 40-43, siempre como patronímico (''hijo de Carea'') que ancla la identidad de Johanán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133377, 'spa', 'Calvicie ritual/de duelo', 'Zona calva o rapada en la cabeza, producida ritualmente como expresión de duelo o aflicción. La ley levítica prohíbe a los sacerdotes hacerse tales marcas (Lv 21:5), y Deuteronomio 14:1 extiende la prohibición a todo Israel, distinguiéndolo de las culturas circundantes. Los textos proféticos emplean la calvicie como señal de juicio divino y calamidad nacional (Is 3:24; 15:2; Ez 7:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133380, 'spa', 'Coraíta (gentilicio)', 'Adjetivo gentilicio derivado de Coré (קֹרַח), que designa al clan levítico descendiente de Coré hijo de Izhar. Aparece como singular colectivo (Éx 6:24; Nm 26:58) y en plural (1 Cr 9:19; 12:7; 26:1; 2 Cr 20:19). Los coraítas servían como porteros y músicos del templo, y probablemente constituyen el gremio tras los salmos ''de los hijos de Coré''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133387, 'spa', 'Calvicie posterior', 'Designa la calvicie especificamente en la parte posterior o coronilla de la cabeza, opuesta consistentemente a la calvicie frontal (גַּבַּחַת) en Levitico 13:42-43, 55. La distincion diagnostica es importante para identificar enfermedades cutaneas: si aparece una llaga blanco-rojiza ''en su calvicie'' (בְּקָרַחְתּוֹ) o ''en su calvicie frontal'', el sacerdote debe examinarla. Las cuatro apariciones ocurren en este unico contexto sacerdotal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133388, 'spa', 'En hostilidad', 'Hostilidad u oposición: disposición de caminar ''en contra'' de Dios, empleada únicamente en Levítico 26. Si Israel camina en קֶרִי (Lev 26:21, 23, 27, 40), Dios responderá en קֶרִי (vv. 24, 28, 41), incluso ''con furor de קֶרִי'' (v. 28). Capta no mera desobediencia sino contrariedad persistente y desafiante contra el pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (133390, 'spa', 'representantes convocados', 'El término identifica a hombres formalmente convocados para servir como representantes tribales en la asamblea gobernante de Israel. Números 1:16 los llama ''los convocados de la congregación''—príncipes de sus tribus ancestrales escogidos para liderar. Números 16:2 describe a los 250 hombres que se unieron a la rebelión de Coré como ''convocados de la asamblea,'' indicando su estatus oficial como consejeros nombrados, lo cual hizo su revuelta aún más grave.');